def region_vote(M,O,wall,bg):
 lab,n=label(M!=wall,structure=st)
 modes={}; counts={}
 for i in range(1,n+1):
  cc=Counter(int(v) for v in M[lab==i] if v not in (wall,bg))
  if cc: modes[i]=cc.most_common(1)[0][0]; counts[i]=cc
 mism=[]; exact=0; unresolved=0
 for r,c in np.argwhere(M==wall):
  adj=set()
  for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
   y,x=r+dr,c+dc
   if 0<=y<M.shape[0] and 0<=x<M.shape[1] and lab[y,x] in modes: adj.add(lab[y,x])
  colors={modes[i] for i in adj}
  if not colors: unresolved+=1; pred=wall
  elif len(colors)==1: pred=next(iter(colors))
  else:
   # unresolved conflict, choose most frequent special pixel count among adjacent regions
   sums=Counter()
   for i in adj:
    for color,nc in counts[i].items(): sums[color]+=nc
   pred=sums.most_common(1)[0][0]
  if pred==int(O[r,c]): exact+=1
  else:mism.append((r,c,int(O[r,c]),pred,adj,colors))
 print('matched',exact,'/',np.sum(M==wall),'unresolved',unresolved,'mismatches',len(mism),mism[:20])
 return lab,modes,counts
