 for r,c in np.argwhere(M==wall):
  votes=Counter()
  for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
   y,x=r+dr,c+dc
   if 0<=y<H and 0<=x<W and reg[y,x] in modes:votes[modes[reg[y,x]]]+=1
  if votes:seeds[(int(r),int(c))]=votes.most_common(1)[0][0]
 # multi-source paths, allow labels tie
 ds={}; labs={}; q=deque()
 for p,col in seeds.items():ds[p]=0;labs[p]={col};q.append(p)
 while q:
  p=q.popleft();r,c=p
  for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
   y,x=r+dr,c+dc
   if 0<=y<H and 0<=x<W and M[y,x]==wall:
    nd=ds[p]+1
    if (y,x) not in ds:ds[(y,x)]=nd;labs[(y,x)]=set(labs[p]);q.append((y,x))
    elif ds[(y,x)]==nd and not labs[(y,x)].issuperset(labs[p]):labs[(y,x)]|=labs[p];q.append((y,x))
